targets.root_selector:
([(
  $label := {"completed":"完成","success":"完成","noop":"無事可做","retry_success":"重試後完成","running":"執行中","waiting":"等待中","not_started":"未開始","pending":"未開始","out_of_window":"未到時段","stale":"待確認","skipped":"略過","at_risk":"趕不上","attention":"應跑未跑","overdue":"逾時","stuck":"卡住","missed":"漏跑","failed":"失敗","error":"失敗","blocked":"中止","watcher_blocked":"被擋住","ready":"就緒","ok":"正常","warn":"注意","fail":"未過","critical":"重大","warning":"注意","healthy":"正常","pending_maturity":"等待成熟","pass":"通過","collecting":"收集中","not_applicable_no_real_intents":"不適用（沒有真實下單）","owner_read_unavailable":"讀不到來源","match":"一致","drift":"漂移","missing":"缺少","invalid":"無效","PASS":"通過","FAIL":"未過"}; $tone := {"completed":"ok","success":"ok","noop":"ok","retry_success":"ok","running":"run","waiting":"idle","not_started":"idle","pending":"idle","out_of_window":"idle","stale":"idle","skipped":"skip","at_risk":"warn","attention":"warn","overdue":"warn","stuck":"bad","missed":"bad","failed":"bad","error":"bad","blocked":"bad","watcher_blocked":"warn","ready":"ok","ok":"ok","warn":"warn","fail":"bad","critical":"bad","warning":"warn","healthy":"ok","pending_maturity":"idle","pass":"ok","collecting":"run","not_applicable_no_real_intents":"idle","owner_read_unavailable":"warn","match":"ok","drift":"warn","missing":"bad","invalid":"bad","PASS":"ok","FAIL":"bad"}; $rank := {"failed":1,"error":1,"blocked":2,"missed":2,"overdue":3,"stuck":4,"watcher_blocked":5,"at_risk":6,"attention":7,"running":8,"waiting":9}; $names := {"market-close-refresh":"Close refresh","finlab-acquire":"FinLab 資料取得","finlab-validate":"FinLab 整理與驗證","finlab-publish":"FinLab 發布與交接","finlab-backfill-watchdog":"FinLab watchdog","update":"Market update","indicator-queue":"Indicator queue","regime-compute":"HMM regime","strategy-learning-mature-evidence":"成熟策略證據","screener":"Screener","allocator-ev-readiness":"Allocator EV","pipeline-inputs":"輸入凍結","pipeline-snapshot":"輸入快照匯出","pipeline-feature-batches":"特徵批次","pipeline-features":"特徵與推論輸入組裝","pipeline-l2":"L2 特徵增強","pipeline-l3":"L3 預測與封存","post-pipeline-chain":"Pipeline callback","allocator-ev-feature-snapshot-backfill":"EV snapshot","verify-v2":"Verify","post-verify-chain":"Verify callback","model-ic-rolling":"Model IC rolling","linucb-reward-ledger":"Reward ledger","adapt":"Adapt params","daily-report":"Daily report","paper-active-postmarket":"Paper active","obsidian-sync":"Obsidian sync","meta-learning-shadow":"Meta shadow","strategy-learning":"Strategy learning","evening-closure":"全鏈完成收據","us-leading":"US leading","news-analyst":"News analyst","morning-setup":"Morning setup","recommendation":"L4 推薦","pre-market-warmup":"Pre-market","premarket-evidence-watchdog":"盤前鏈監看","dataset-snapshot-export":"Research snapshot","active8-oof-daily":"Active-8 daily","allocator-ev-lifecycle-watchdog":"EV lifecycle","finlab-v4-backfill":"FinLab canonical","pipeline":"L3 Pipeline","ml-predict":"ML Predict","intraday-check":"Intraday check","eod-exit":"EOD exit","post-close-price-refresh":"Close price","daily-snapshot":"Daily snapshot","rescore-10":"10:00 re-score","rescore-11":"11:00 re-score","rescore-12":"12:00 re-score","rescore-1230":"12:30 re-score","weekly-audit":"Weekly audit","storage-integrity-audit":"Storage integrity","model-ic-full-check":"Model IC full","weekly-backtest":"Validation / MC","alpha-quality":"Alpha quality","active8-oof-weekly":"Active-8 weekly","weekly-optuna":"Drift research","sector-leaders":"Sector leaders","adaptive-meta-policy-replay":"Meta replay","s12-smcvwap-calibration":"S12 calibration","linucb-multiplier-replay":"LinUCB replay","weekly-cleanup":"Weekly cleanup","weekly-readiness":"Weekly root","monthly-strategy-mining":"Strategy mining","monthly-optuna":"Monthly search","active8-oof-monthly":"Active-8 monthly","monthly-readiness":"Monthly root"};
  $now := $toMillis($$.generated_at);
  $watch := function($r) { $type($r.watcher) = 'boolean' ? $r.watcher : $r.stage_id in ['intraday-check'] };
  $ds := function($r) { $r.display_status = 'blocked' and $watch($r) ? 'watcher_blocked' : $r.display_status };
  $rk := function($r) {( $k := $lookup($rank, $ds($r)); $k ? $k : 99 )};
  $pos := function($r) {( $p := $r.position; $type($p) = 'number' ? $p : 999 )};
  $rows := $$.rows[active = true and stage_id];
  $done := $rows[$ds($) in ['completed', 'success', 'noop', 'retry_success', 'skipped']];
  $items := $sort($rows[$rk($) < 99], function($a, $b) { $rk($a) = $rk($b) ? $pos($a) > $pos($b) : $rk($a) > $rk($b) });
  $todo := $count($rows) - $count($done) - $count($items);
  $n := $count($items);
  $word := function($r) {(
    $s := $ds($r); $l := $lookup($label, $s); $t := $lookup($tone, $s); $l := $l ? $l : '狀態異常';
    $b := $r.error_brief ? ($w := $lookup({"資料庫過載":"資料庫過載","執行逾時":"執行逾時","上游資料未就緒":"上游未就緒","外部服務額度用盡":"額度用盡","服務暫時無法使用":"服務不可用","執行錯誤，細節見 log":"細節見 log"}, $r.error_brief); $w ? $w : '細節見 log') : $r.error ? '細節見 log' : '';
    $m := $r.started_at ? ($now - $toMillis($r.started_at)) / 60000 : null;
    ($t ? $t : 'idle') & '|' & (
      $s in ["failed","error","blocked","missed","stuck"] and $b ? ($b = '細節見 log' ? $l & '（細節見 log）' : $l & '：' & $b)
      : $s in ["running","stuck","overdue","at_risk"] and $r.started_at and $not($r.completed_at) ? $l & '・已 ' & ($m != null ? ($m < 60 ? $string($round($m)) & ' 分' : $m < 1440 ? $string($round($m / 60, 1)) & ' h'
  : $string($round($m / 1440, 1)) & ' 天') : '—')
      : $l)
  )};
  $shown := ($n > 6 ? $items[[0..4]] : $items).{ 'stage': ($m := $lookup($names, stage_id); $m ? $m : label ? label : '其他站'), 'status': $word($) };
  $out := $append($append($append($shown,
    $n > 6 ? [{ 'stage': '另有 ' & $string($n - 5) & ' 站', 'status': 'idle|看完整版' }] : []),
    $count($done) > 0 ? [{ 'stage': '其他 ' & $string($count($done)) & ' 站', 'status': 'ok|已完成／略過' }] : []),
    $todo > 0 ? [{ 'stage': '其他 ' & $string($todo) & ' 站', 'status': 'idle|未開始' }] : []);
  $count($out) > 0 ? $out : []
)])
